import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import Alert from './Alert';
import { motion } from 'framer-motion';

const Header = () => {
    const [isLoggedin, setIsLoggedin] = useState(false);
    const [isAlertOpen, setIsAlertOpen] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const session = sessionStorage.getItem('session');
        if (session) {
            setIsLoggedin(true);
        }
    }, []);

    const session = sessionStorage.getItem('session');
    const userData = session ? JSON.parse(session) : null;

    const handleAuthClick = () => {
        if (isLoggedin) {
            setIsAlertOpen(true);
        } else {
            navigate('/');
        }
    };

    const handleConfirmLogout = () => {
        sessionStorage.removeItem('session');
        setIsLoggedin(false);
        navigate('/');
    };

    return (
        <header className="fixed top-0 min-w-[100%] z-50 flex justify-between items-center px-margin-mobile md:px-margin-desktop py-4 max-w-container-max mx-auto bg-surface dark:bg-surface-dim border-b border-outline-variant dark:border-outline">
            <Alert
                isOpen={isAlertOpen}
                onClose={() => setIsAlertOpen(false)}
                onConfirm={handleConfirmLogout}
                title="Confirm Logout"
                message="Are you sure you want to logout of your account?"
                type="danger"
                confirmText="Logout"
                cancelText="Cancel"
            />
            <div className="flex items-center cursor-pointer active:opacity-80">
                <Link to={isLoggedin ? "/home" : "/"} className="flex items-center gap-1 hover:no-underline">
                    <span className="material-symbols-outlined text-primary dark:text-primary-fixed" style={{ fontSize: '24px' }}>shield</span>
                    <span className="font-headline-md text-headline-md font-bold text-primary dark:text-primary-fixed !text-[24px]">TheEntrance</span>
                </Link>
            </div>
            {isLoggedin && <nav class="hidden md:flex items-center space-x-8">
                <motion.Link
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    transition={{ duration: 0.2, }}
                    to="/products" className="text-on-surface-variant hover:text-secondary transition-colors duration-200 font-body-md text-body-md">Products</motion.Link>
                <motion.Link
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    transition={{ duration: 0.2, }}
                    to="/solutions" className="text-on-surface-variant hover:text-secondary transition-colors duration-200 font-body-md text-body-md">Solutions</motion.Link>
                <motion.Link
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    to="/support" className="text-on-surface-variant hover:text-secondary transition-colors duration-200 font-body-md text-body-md">Support</motion.Link>
                <motion.Link
                    whileHover={{ scale: 1.02 }}
                    whileTap={{ scale: 0.98 }}
                    transition={{ duration: 0.2, }}
                    to="/enterprise" className="text-on-surface-variant hover:text-secondary transition-colors duration-200 font-body-md text-body-md">Enterprise</motion.Link>
            </nav>}
            <div className="flex justify-center items-center gap-3">
                {isLoggedin && <span className='text-secondary font-bold dark:text-primary-fixed-container'>Hey {userData.first_name}!</span>}
                <button
                    className="px-6 py-2 bg-primary dark:bg-primary-fixed text-white font-semibold rounded-full shadow-sm hover:scale-105 hover:cursor-pointer  active:scale-95 transition-all duration-200 flex items-center justify-center"
                    onClick={handleAuthClick}
                >
                    {isLoggedin ? "Logout" : "Login"}
                </button>
            </div>
        </header>
    );
};

export default Header;
